using System.Text;

namespace Codalus.Workbench.Projects;

public enum ItemTemplateSource
{
    /// <summary>Generated by Codalus: no trust needed, works offline, previews its content.</summary>
    BuiltIn,

    /// <summary>A <c>dotnet new</c> item template, instantiated by the build host.</summary>
    DotnetNew,
}

/// <summary>What a new item is made for: the project's language and kind, its folder's namespace, and the chosen name.</summary>
public sealed record ItemTemplateContext(string Name, string Namespace, bool FileScopedNamespace = true);

/// <summary>
/// An item template of Add New Item (ADR 0033). <see cref="Languages"/> empty means any language; <see cref="Tags"/> are
/// <c>dotnet new</c>'s tags (Web, MAUI, Test…), which decide the project kinds it is offered for. Built-in templates
/// make their content with <see cref="Content"/> and may give the file an item type and metadata.
/// </summary>
public sealed record ItemTemplate(string Name, string ShortName, string Category, string Description, string DefaultName, string Extension)
{
    public ItemTemplateSource Source { get; init; } = ItemTemplateSource.BuiltIn;

    public IReadOnlyList<string> Languages { get; init; } = [];

    public IReadOnlyList<string> Tags { get; init; } = [];

    public Func<ItemTemplateContext, string>? Content { get; init; }

    /// <summary>The Build Action the new file gets (null: the one the globs give it).</summary>
    public string? ItemType { get; init; }

    /// <summary>Item metadata the new file gets (a text template's <c>Generator</c>…); <c>{name}</c> is the file's base name.</summary>
    public IReadOnlyDictionary<string, string>? Metadata { get; init; }

    /// <summary>The file name for <paramref name="name"/> (the extension added unless typed).</summary>
    public string FileName(string name) =>
        Extension.Length == 0 || name.EndsWith(Extension, StringComparison.OrdinalIgnoreCase) ? name : name + Extension;

    public string Id => (Source == ItemTemplateSource.BuiltIn ? "builtin:" : "dotnet:") + ShortName;
}

/// <summary>The project Add New Item adds to: its language and the kinds that filter the templates.</summary>
public sealed record ItemTemplateProject(string Language, bool IsWeb = false, bool IsMaui = false, bool IsTest = false, bool IsWpf = false, bool IsWinForms = false, bool IsMobile = false)
{
    /// <summary>The language of a project file: C#, F# or VB.</summary>
    public static string LanguageOf(string projectPath) => Path.GetExtension(projectPath).ToLowerInvariant() switch
    {
        ".fsproj" => "F#",
        ".vbproj" => "VB",
        _ => "C#",
    };
}

/// <summary>The built-in item templates, and the filter by project kind (ADR 0033).</summary>
public static class ItemTemplates
{
    /// <summary>Tags that tie a template to a kind of project.</summary>
    private static readonly (string Tag, Func<ItemTemplateProject, bool> Applies)[] s_kindTags =
    [
        ("Web", p => p.IsWeb),
        ("ASP.NET", p => p.IsWeb),
        ("Blazor", p => p.IsWeb),
        ("MAUI", p => p.IsMaui),
        ("Android", p => p.IsMaui || p.IsMobile),
        ("iOS", p => p.IsMaui || p.IsMobile),
        ("Mac Catalyst", p => p.IsMaui || p.IsMobile),
        ("macOS", p => p.IsMaui || p.IsMobile),
        ("Mobile", p => p.IsMaui || p.IsMobile),
        ("Tizen", p => p.IsMaui),
        ("WinUI", p => p.IsMaui),
        ("WPF", p => p.IsWpf),
        ("WinForms", p => p.IsWinForms),
        ("Test", p => p.IsTest),
        ("MSTest", p => p.IsTest),
        ("NUnit", p => p.IsTest),
        ("xUnit", p => p.IsTest),
    ];

    /// <summary>
    /// Whether a template is offered for a project: its languages include the project's (or it has none), and when its
    /// tags name kinds of projects, the project is one of them.
    /// </summary>
    public static bool AppliesTo(ItemTemplate template, ItemTemplateProject project)
    {
        if (template.Languages.Count > 0 && !template.Languages.Contains(project.Language, StringComparer.OrdinalIgnoreCase))
        {
            return false;
        }

        var kinds = s_kindTags.Where(k => template.Tags.Contains(k.Tag, StringComparer.OrdinalIgnoreCase)).ToList();
        return kinds.Count == 0 || kinds.Any(k => k.Applies(project));
    }

    /// <summary>
    /// The templates Add New Item offers: the built-in ones, then the <c>dotnet new</c> ones whose short names aren't
    /// built in (a built-in template wins: it needs no trust, works offline and previews its content).
    /// </summary>
    public static IReadOnlyList<ItemTemplate> Merge(IEnumerable<ItemTemplate> dotnetNew) =>
        [.. BuiltIn, .. dotnetNew.Where(t => !BuiltIn.Any(b => b.ShortName.Equals(t.ShortName, StringComparison.OrdinalIgnoreCase)))];

    public static IReadOnlyList<ItemTemplate> BuiltIn { get; } =
    [
        Code("class", "Class", "An empty class.", "Class1", c => CSharp(c, $"internal class {c.Name}\n{{\n}}\n")),
        Code("interface", "Interface", "An empty interface.", "IInterface1", c => CSharp(c, $"internal interface {c.Name}\n{{\n}}\n")),
        Code("record", "Record", "A record class.", "Record1", c => CSharp(c, $"internal record {c.Name}();\n")),
        Code("struct", "Struct", "A struct.", "Struct1", c => CSharp(c, $"internal struct {c.Name}\n{{\n}}\n")),
        Code("enum", "Enum", "An enumeration.", "Enum1", c => CSharp(c, $"internal enum {c.Name}\n{{\n}}\n")),
        Code("codefile", "Code File", "An empty C# file.", "CodeFile1", _ => string.Empty),
        Code("globalusings", "Global Usings", "A file of global using directives.", "GlobalUsings", _ => "global using System;\n"),
        General("text", "Text File", "An empty text file.", "TextFile1", ".txt", _ => string.Empty),
        General("json", "JSON File", "An empty JSON file.", "JsonFile1", ".json", _ => "{\n}\n", "Data"),
        General("appsettings", "App Settings File", "An appsettings.json file for configuration.", "appsettings", ".json", _ => "{\n  \"Logging\": {\n    \"LogLevel\": {\n      \"Default\": \"Information\"\n    }\n  }\n}\n", "General", metadata: new Dictionary<string, string> { ["CopyToOutputDirectory"] = "PreserveNewest" }),
        General("xml", "XML File", "An XML file.", "XmlFile1", ".xml", _ => "<?xml version=\"1.0\" encoding=\"utf-8\"?>\n", "Data"),
        General("markdown", "Markdown File", "A Markdown document.", "README", ".md", c => $"# {c.Name}\n"),
        General("resx", "Resources File", "Strings and other resources, with a strongly typed class generated from them.", "Resource1", ".resx", _ => Resx, "General",
            itemType: "EmbeddedResource", metadata: new Dictionary<string, string> { ["Generator"] = "ResXFileCodeGenerator", ["LastGenOutput"] = "{name}.Designer.cs" }),
        General("t4", "Text Template", "A T4 text template that generates a file of the project.", "TextTemplate1", ".tt", _ => TextTemplate, "General",
            metadata: new Dictionary<string, string> { ["Generator"] = "TextTemplatingFileGenerator", ["LastGenOutput"] = "{name}.cs" }),
        General("html", "HTML Page", "An HTML page.", "HtmlPage1", ".html", c => $"<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"utf-8\" />\n    <title>{c.Name}</title>\n</head>\n<body>\n\n</body>\n</html>\n", "Web", tags: ["Web"]),
        General("css", "Style Sheet", "A CSS style sheet.", "StyleSheet1", ".css", _ => "body {\n}\n", "Web", tags: ["Web"]),
        General("javascript", "JavaScript File", "A JavaScript file.", "JavaScript1", ".js", _ => string.Empty, "Web", tags: ["Web"]),
        General("typescript", "TypeScript File", "A TypeScript file.", "TypeScript1", ".ts", _ => string.Empty, "Web", tags: ["Web"]),
    ];

    private static ItemTemplate Code(string shortName, string name, string description, string defaultName, Func<ItemTemplateContext, string> content) =>
        new(name, shortName, "Code", description, defaultName, ".cs") { Languages = ["C#"], Content = content };

    private static ItemTemplate General(string shortName, string name, string description, string defaultName, string extension, Func<ItemTemplateContext, string> content, string category = "General", IReadOnlyList<string>? tags = null, string? itemType = null, IReadOnlyDictionary<string, string>? metadata = null) =>
        new(name, shortName, category, description, defaultName, extension) { Content = content, Tags = tags ?? [], ItemType = itemType, Metadata = metadata };

    /// <summary>A C# file with the context's namespace, file scoped when the language version allows it.</summary>
    public static string CSharp(ItemTemplateContext context, string body)
    {
        if (context.Namespace.Length == 0)
        {
            return body;
        }

        if (context.FileScopedNamespace)
        {
            return $"namespace {context.Namespace};\n\n{body}";
        }

        var indented = new StringBuilder();
        foreach (var line in body.TrimEnd('\n').Split('\n'))
        {
            indented.Append(line.Length == 0 ? string.Empty : "    ").Append(line).Append('\n');
        }

        return $"namespace {context.Namespace}\n{{\n{indented}}}\n";
    }

    /// <summary>
    /// The namespace of a new file: the root namespace, then the folders from the project to the file, each made a valid
    /// identifier (as Visual Studio does).
    /// </summary>
    public static string NamespaceFor(string rootNamespace, string projectDirectory, string folder)
    {
        var segments = new List<string>();
        if (rootNamespace.Length > 0)
        {
            segments.Add(rootNamespace);
        }

        var relative = Path.GetRelativePath(projectDirectory, folder);
        if (relative != "." && !relative.StartsWith("..", StringComparison.Ordinal))
        {
            segments.AddRange(relative.Split(['\\', '/'], StringSplitOptions.RemoveEmptyEntries));
        }

        return string.Join('.', segments.SelectMany(s => s.Split('.', StringSplitOptions.RemoveEmptyEntries)).Select(Identifier));
    }

    /// <summary>A valid C# identifier for a name: other characters become underscores, a leading digit gets one.</summary>
    public static string Identifier(string name)
    {
        var text = new string([.. name.Select(c => char.IsLetterOrDigit(c) || c == '_' ? c : '_')]);
        return text.Length > 0 && char.IsDigit(text[0]) ? "_" + text : text;
    }

    /// <summary>Whether the target frameworks allow file-scoped namespaces by default (C# 10: .NET 6 and later).</summary>
    public static bool SupportsFileScopedNamespaces(IEnumerable<string> targetFrameworks) =>
        targetFrameworks.All(f => f.StartsWith("net", StringComparison.OrdinalIgnoreCase) && !f.StartsWith("netstandard", StringComparison.OrdinalIgnoreCase)
                                  && !f.StartsWith("netcoreapp", StringComparison.OrdinalIgnoreCase)
                                  && int.TryParse(f.AsSpan(3, Math.Max(0, f.IndexOf('.', StringComparison.Ordinal) - 3)), out var major) && major >= 6);

    private const string Resx = """
        <?xml version="1.0" encoding="utf-8"?>
        <root>
          <resheader name="resmimetype">
            <value>text/microsoft-resx</value>
          </resheader>
          <resheader name="version">
            <value>2.0</value>
          </resheader>
          <resheader name="reader">
            <value>System.Resources.ResXResourceReader, System.Windows.Forms, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089</value>
          </resheader>
          <resheader name="writer">
            <value>System.Resources.ResXResourceWriter, System.Windows.Forms, Version=4.0.0.0, Culture=neutral, PublicKeyToken=b77a5c561934e089</value>
          </resheader>
        </root>

        """;

    private const string TextTemplate = """
        <#@ template language="C#" #>
        <#@ output extension=".cs" #>
        // <auto-generated/>

        """;
}
